<div class="admin-table-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>عنوان</th><th>وضعیت</th><th>آخرین ذخیره</th><th>عملیات</th></tr></thead><tbody>@forelse($drafts as $draft)<tr><td>{{ data_get($draft->payload,'title') ?: 'بدون عنوان' }}</td><td><span class="status-badge active">{{ $draft->status==='saved'?'ذخیره‌شده':'پیش‌نویس' }}</span></td><td>{{ $draft->updated_at?->format('Y/m/d H:i') }}</td><td><button type="button" class="action-btn edit" onclick="loadDraft({{ $draft->id }})">باز کردن داده</button><button type="button" class="action-btn edit" onclick="deleteDraft({{ $draft->id }})">حذف</button></td></tr>@empty<tr><td colspan="4" class="admin-empty">پیش‌نویسی وجود ندارد.</td></tr>@endforelse</tbody></table></div></div>{{ $drafts->links() }}</div>
