@push('scripts')<script>async function loadDraft(id){const r=await fetch(`{{ url('/admin/products/drafts') }}/${id}`,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok||!d.ok)return alert(d.message||'خطا در دریافت پیش‌نویس');prompt('داده پیش‌نویس (JSON فقط برای بررسی):',JSON.stringify(d.draft.payload,null,2));}async function deleteDraft(id){if(!confirm('این پیش‌نویس حذف شود؟'))return;const r=await fetch(`{{ url('/admin/products/drafts') }}/${id}`,{method:'DELETE',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}',Accept:'application/json'}});if(r.ok)location.reload();}</script>@endpush